window.SF2MUS={wasm:"",proc:"// AudioWorklet: CPS1 sound board (Z80 + YM2151 + OKI) compiled to wasm from snd/sndcore.cpp.\nclass SF2Snd extends AudioWorkletProcessor{\n  constructor(o){super();const p=o.processorOptions,st=()=>0;\n    const inst=new WebAssembly.Instance(new WebAssembly.Module(p.wasm),{wasi_snapshot_preview1:{fd_close:st,fd_seek:st,fd_write:st}});\n    const X=this.x=inst.exports;if(X._initialize)X._initialize();\n    new Uint8Array(X.memory.buffer,X.snd_rom(),0x10000).set(p.z80);new Uint8Array(X.memory.buffer,X.snd_oki(),0x40000).set(p.oki);\n    X.snd_reset();for(const c of p.init||[])X.snd_cmd(c);this.e=0;this.n=0;\n    this.port.onmessage=e=>{const m=e.data;if(m.c!==undefined)X.snd_cmd(m.c);if(m.o)X.snd_oki_play(m.o[0],m.o[1]);if(m.g!==undefined)X.snd_gain(m.g);};\n    this.port.postMessage({ready:1});}\n  process(i,o){const out=o[0][0],X=this.x,n=out.length;X.snd_render(n,sampleRate);out.set(new Float32Array(X.memory.buffer,X.snd_buf(),n));\n    for(let k=0;k<n;k++)this.e+=out[k]*out[k];this.n+=n;if(this.n>=sampleRate/4){this.port.postMessage({rms:Math.sqrt(this.e/this.n)});this.e=0;this.n=0;}\n    for(let c=1;c<o[0].length;c++)o[0][c].set(out);return true;}}\nregisterProcessor('sf2snd',SF2Snd);\n"};
